package com.brightloop.invoice;
import com.brightloop.audit.AuditLogService;import com.brightloop.discount.Discount;import com.brightloop.plan.BillingFrequency;import com.brightloop.subscription.*;import com.brightloop.tax.*;import java.math.*;import java.time.*;import java.util.*;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class BillingService {
 private static final Logger log=LoggerFactory.getLogger(BillingService.class);private final SubscriptionRepository subscriptions;private final InvoiceRepository invoices;private final TaxRepository taxes;private final com.brightloop.notification.EmailNotificationService emails;private final AuditLogService audit;
 public BillingService(SubscriptionRepository s,InvoiceRepository i,TaxRepository t,com.brightloop.notification.EmailNotificationService emails,AuditLogService audit){subscriptions=s;invoices=i;taxes=t;this.emails=emails;this.audit=audit;}
 @Transactional public int runDueBilling(){LocalDate today=LocalDate.now();int created=0;for(Subscription expired:subscriptions.findExpiredActive(today)){try{if(expired.isAutoCloseOnExpiry())expired.close(false);}catch(Exception e){log.error("Could not auto-close expired subscription {}",expired.getSubscriptionNumber(),e);}}for(Subscription sub:subscriptions.findDueForBilling(today)){try{if(invoices.findBySubscriptionIdAndBillingPeriodStart(sub.getId(),sub.getNextBillingDate()).isPresent()){advance(sub,today);continue;}createRecurringInvoice(sub,today);advance(sub,today);created++;}catch(Exception e){log.error("Recurring billing failed for subscription {}",sub.getSubscriptionNumber(),e);}}return created;}
 @Transactional(readOnly=true) public java.util.List<InvoiceDtos.Response> list(){return invoices.findAll().stream().sorted(Comparator.comparing(Invoice::getIssueDate).reversed()).map(InvoiceDtos.Response::of).toList();}
 @Transactional(readOnly=true) public java.util.List<InvoiceDtos.Response> listForCustomer(String email){return invoices.findByCustomerEmailIgnoreCase(email).stream().sorted(Comparator.comparing(Invoice::getIssueDate).reversed()).map(InvoiceDtos.Response::of).toList();}
 @Transactional(readOnly=true) public InvoiceDtos.Response get(Long id){return InvoiceDtos.Response.of(invoices.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invoice not found")));}
 @Transactional public InvoiceDtos.Response cancel(Long id){Invoice invoice=invoices.findForUpdate(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invoice not found"));try{invoice.cancel();}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}return InvoiceDtos.Response.of(invoice);}
 @Transactional public InvoiceDtos.Response send(Long id){Invoice invoice=invoices.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invoice not found"));if("CANCELLED".equals(invoice.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Cancelled invoices cannot be sent");emails.invoiceReminder(invoice.getCustomer().getEmail(),invoice.getInvoiceNumber(),invoice.getDueDate().toString());return InvoiceDtos.Response.of(invoice);}
 @Transactional(readOnly=true) public InvoiceDtos.Response getForCustomer(Long id,String email){Invoice invoice=invoices.findById(id).filter(i->i.getCustomer().getEmail().equalsIgnoreCase(email)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invoice not found"));return InvoiceDtos.Response.of(invoice);}
 @Transactional public InvoiceDtos.Response issueForSubscription(Long id){var s=subscriptions.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Subscription not found"));if(!"ACTIVE".equals(s.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only active subscriptions can be billed");if(s.getNextBillingDate()==null||s.getNextBillingDate().isAfter(LocalDate.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Subscription is not due for billing");return InvoiceDtos.Response.of(createRecurringInvoice(s,LocalDate.now()));}
 private Invoice createRecurringInvoice(Subscription sub,LocalDate today){LocalDate periodStart=sub.getNextBillingDate();if(periodStart==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Subscription has no next billing date");if(invoices.findBySubscriptionIdAndBillingPeriodStart(sub.getId(),periodStart).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Invoice already exists for this billing period");LocalDate periodEnd=advanceOne(periodStart,sub.getBillingFrequency()).minusDays(1);if(sub.getExpiryDate()!=null&&periodEnd.isAfter(sub.getExpiryDate()))periodEnd=sub.getExpiryDate();BigDecimal subtotal=BigDecimal.ZERO,taxTotal=BigDecimal.ZERO;List<LineTotals> totals=new ArrayList<>();for(var line:sub.getLines()){BigDecimal base=line.getUnitPrice().multiply(BigDecimal.valueOf(line.getQuantity())).setScale(2,RoundingMode.HALF_UP);var tax=taxFor(line.getProduct().getId(),base,line.getQuantity(),today);subtotal=subtotal.add(base);taxTotal=taxTotal.add(tax.amount);totals.add(new LineTotals(line,base,tax.amount,tax.percentRate));}BigDecimal discountAmount=discountFor(sub.getDiscount(),subtotal,today);BigDecimal total=subtotal.add(taxTotal).subtract(discountAmount).max(BigDecimal.ZERO).setScale(2,RoundingMode.HALF_UP);String number="INV-"+today.getYear()+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();Invoice invoice=invoices.save(new Invoice(number,sub.getCustomer(),sub,null,periodStart,periodEnd,today,today.plusDays(14),subtotal,taxTotal,discountAmount,total));for(var t:totals)invoice.addLine(new InvoiceLine(invoice,t.line.getProduct(),t.line.getDescription(),t.line.getQuantity(),t.line.getUnitPrice(),t.rate,t.tax,t.base.add(t.tax)));if(sub.getDiscount()!=null&&discountAmount.signum()>0)sub.getDiscount().consume();audit.record("system","GENERATE","INVOICE",invoice.getId(),number+" for "+sub.getSubscriptionNumber());emails.invoice(sub.getCustomer().getEmail(),number,total.toPlainString());return invoice;}
 private TaxTotal taxFor(Long productId,BigDecimal base,int quantity,LocalDate date){BigDecimal amount=BigDecimal.ZERO,percent=BigDecimal.ZERO;for(Tax tax:taxes.findAll()){if(!tax.isActive()||(tax.getProduct()!=null&&!tax.getProduct().getId().equals(productId))||(tax.getEffectiveStart()!=null&&date.isBefore(tax.getEffectiveStart()))||(tax.getEffectiveEnd()!=null&&date.isAfter(tax.getEffectiveEnd())))continue;if("PERCENTAGE".equals(tax.getTaxType())){percent=percent.add(tax.getRate());amount=amount.add(base.multiply(tax.getRate()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP));}else amount=amount.add(tax.getRate().multiply(BigDecimal.valueOf(quantity)).setScale(2,RoundingMode.HALF_UP));}return new TaxTotal(amount,percent);}
 private BigDecimal discountFor(Discount discount,BigDecimal base,LocalDate today){if(discount==null||!discount.eligible(today))return BigDecimal.ZERO;BigDecimal amount="PERCENTAGE".equals(discount.getDiscountType())?base.multiply(discount.getValue()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP):discount.getValue();return amount.min(base).max(BigDecimal.ZERO);}
 private void advance(Subscription sub,LocalDate today){LocalDate next=advanceOne(sub.getNextBillingDate(),sub.getBillingFrequency());while(!next.isAfter(today))next=advanceOne(next,sub.getBillingFrequency());if(sub.getExpiryDate()!=null&&next.isAfter(sub.getExpiryDate())){if(sub.isAutoCloseOnExpiry())sub.close(false);else sub.billed(null);}else sub.billed(next);}
 public static LocalDate advanceOne(LocalDate date,BillingFrequency frequency){return switch(frequency){case DAILY->date.plusDays(1);case WEEKLY->date.plusWeeks(1);case MONTHLY->date.plusMonths(1);case YEARLY->date.plusYears(1);};}
 private record TaxTotal(BigDecimal amount,BigDecimal percentRate){}private record LineTotals(SubscriptionLine line,BigDecimal base,BigDecimal tax,BigDecimal rate){}
}
